      else if (event.key === 'Home') next = 0
      else if (event.key === 'End') next = this.practices.length - 1
      else return
      event.preventDefault()
      this.activePractice = next
      this.$nextTick(() => document.getElementById('practice-tab-' + this.practices[next].id).focus())
    },
    showModal(type) {
