    closeModal() {
      this.modal = null
      document.body.style.overflow = this._previousOverflow
      this.$nextTick(() => {
        if (this._returnFocus && this._returnFocus.isConnected) this._returnFocus.focus()
      })
    },
    trapFocus(event) {
      const elements = this.$refs.modal.querySelectorAll('button, a[href], input, select, textarea, [tabindex="0"]')
      const first = elements[0]
      const last = elements[elements.length - 1]
      if (event.shiftKey && document.activeElement === first) { event.preventDefault(); last.focus() }
      else if (!event.shiftKey && document.activeElement === last) { event.preventDefault(); first.focus() }
    },
    prepareInquiry() {
      if (!this.inquiry.message) return
      this.inquiryText = this.lang === 'en'
        ? 'Xin’an Zen Temple inquiry\nTopic: ' + this.localizedTopic(this.inquiry.topic) + '\nName: ' + (this.inquiry.name || 'Not provided') + '\nMessage:\n' + this.inquiry.message
        : '心安禅寺咨询\n主题：' + this.inquiry.topic + '\n称呼：' + (this.inquiry.name || '未填写') + '\n咨询内容：\n' + this.inquiry.message
      this.copyStatus = ''
    },
    copyInquiry() {
      // Promise syntax avoids adding an async runtime dependency to this older Vue 2 project.
      if (navigator.clipboard && window.isSecureContext) {
        navigator.clipboard.writeText(this.inquiryText).then(() => {
          this.copyStatus = 'copied'
        }).catch(() => this.copyInquiryFallback())
      } else this.copyInquiryFallback()
    },
    copyInquiryFallback() {
      const field = this.$refs.copyText
      if (!field) return
      field.focus()
      field.select()
      try {
        this.copyStatus = document.execCommand('copy') ? 'copied' : 'manual'
      } catch (error) {
        this.copyStatus = 'manual'
      }
    }
  }
}
